impl Args {
    #[allow(clippy::too_many_arguments)]
    fn dir_entry_dict(
        &self,
        file: &FileInfo,
        display_name: &str,
        metadata: Option<&std::fs::Metadata>,
        du: bool,
        signals: &Signals,
        use_mime_type: bool,
    ) -> Result<Value, ShellError> {
        let span = self.call_span;
        let filename = expand_to_real_path(file.path());

        #[cfg(windows)]
        if metadata.is_none() {
            return Ok(windows_helper::dir_entry_dict_windows_fallback(
                &filename,
                display_name,
                span,
                self.long,
            ));
        }

        let mut record = Record::new();
        let mut file_type = "unknown".to_string();

        record.push("name", Value::string(display_name, span));

        if let Some(md) = metadata {
            file_type = get_file_type(md, display_name, use_mime_type);
            record.push("type", Value::string(file_type.clone(), span));
        } else {
            record.push("type", Value::nothing(span));
        }

        if self.long {
            if metadata.is_some() {
                record.push(
                    "target",
                    if file.is_symlink() {
                        if let Ok(path_to_link) = filename.read_link() {
                            Value::string(path_to_link.to_string_lossy(), span)
                        } else {
                            Value::string("Could not obtain target file's path", span)
                        }
                    } else {
                        Value::nothing(span)
                    },
                );
            }
        }

        if self.long {
            if metadata.is_some() {
                record.push("readonly", Value::bool(file.readonly(), span));
                if let Some(md) = metadata {
                    append_unix_listing_columns(&mut record, md, span);
                }
            }
        }

        record.push(
            "size",
            if metadata.is_some() {
                let zero_sized = file_type == "pipe"
                    || file_type == "socket"
                    || file_type == "char device"
                    || file_type == "block device";

                if file.is_dir() {
                    if du {
                        Value::filesize(apparent_dir_size(&filename, span, signals)? as i64, span)
                    } else {
                        Value::filesize(file.size() as i64, span)
                    }
                } else if file.is_file() {
                    Value::filesize(file.size() as i64, span)
                } else if file.is_symlink() {
                    Value::filesize(file.size() as i64, span)
                } else if zero_sized {
                    Value::filesize(0, span)
                } else {
                    Value::nothing(span)
                }
            } else {
                Value::nothing(span)
            },
        );

        if self.long {
            append_created_accessed(&mut record, metadata, span);
        }

        record.push("modified", {
            let mut val = Value::nothing(span);
            if let Some(m) = file.modified() {
                if let Some(local) = try_convert_to_local_date_time(m) {
                    val = Value::date(local.with_timezone(local.offset()), span);
                }
            }
            val
        });

        Ok(Value::record(record, span))
    }

